runs.map((run) => {
    let value = escapeInlineMarkdown(run.text);
    const style = run.style;
    if (!style) return value;
    if (style.bold) value = `**${value}**`;
    if (style.italic) value = `*${value}*`;
    if (style.strike) value = `~~${value}~~`;
    if (style.underline) value = `<u>${value}</u>`;
    if (style.color) value = `<span style="color:${style.color}">${value}</span>`;
    return value;
  }).join

text.split(/\r?\n/)
    .map((line) => {
      const match = line.match(/^([ \t]*)(.*?)\s*$/);
      const whitespace = (match?.[1] ?? "").replaceAll("\t", "    ").length;
      return { indent: whitespace, text: match?.[2]?.trim() ?? "" };
    })
    .filter

lines.map((line, index) => {
    const level = levelOf(line.indent);
    if (index === 0 && hasHierarchy) return `# ${line.text}`;
    const adjustedLevel = hasHierarchy ? Math.max(0, level - levelOf(lines[0]!.indent) - 1) : level;
    return `${"  ".repeat(adjustedLevel)}- ${line.text}`;
  }).join

new ArticleStyleModal(this.app, this.document.articleStyle, (style) => {
      this.mutate(() => { this.document.articleStyle = style; });
    }).open

new AppearanceModal(
      this.app,
      this.getAppearance(),
      {
        articleNumberingMode: this.document.root.articleNumberingMode ?? (this.document.root.skipArticleNumbering === true ? "none" : undefined),
        articleNumberingLevel: this.document.root.articleNumberingLevel
      },
      this.document.view?.articleTocMaxDepth,
      this.options.articleTocMaxDepth,
      (appearance, numbering, articleTocMaxDepth) => this.mutate(() => {
        this.document.appearance = appearance;
        this.document.root.articleNumberingMode = numbering.articleNumberingMode;
        this.document.root.articleNumberingLevel = numbering.articleNumberingMode === "manual" ? numbering.articleNumberingLevel : undefined;
        this.document.root.skipArticleNumbering = numbering.articleNumberingMode === "none" || undefined;
        const view = { ...(this.document.view ?? {}) };
        if (articleTocMaxDepth === undefined) delete view.articleTocMaxDepth;
        else view.articleTocMaxDepth = articleTocMaxDepth;
        this.document.view = Object.keys(view).length ? view : undefined;
      }),
      () => this.mutate(() => {
        this.document.appearance = undefined;
        this.document.root.articleNumberingMode = undefined;
        this.document.root.articleNumberingLevel = undefined;
        this.document.root.skipArticleNumbering = undefined;
        if (this.document.view) {
          delete this.document.view.articleTocMaxDepth;
          if (!Object.keys(this.document.view).length) this.document.view = undefined;
        }
      })
    ).open

new TableEditModal(this.app, selected.table, (table) => {
      this.mutate(() => { selected.table = table; });
    }).open

new CodeEditModal(this.app, selected.code, (code) => {
      this.mutate(() => { selected.code = code; });
    }).open

new FormulaEditModal(this.app, (source) => {
      this.mutate(() => {
        const blocks = nodeContentBlocks(selected);
        const formula = `$$${source}$$`;
        const emptyText = blocks.find((block): block is MindMapTextContentBlock => block.type === "text" && !block.text.trim());
        if (emptyText) {
          emptyText.text = formula;
          emptyText.richText = undefined;
        } else {
          blocks.push({ id: newId(), type: "text", text: formula });
        }
        selected.content = blocks;
        syncNodeLegacyFields(selected);
      });
    }).open

ensureMathJax().then(() => {
      if (container.isConnected) renderRichTextRuns(container, runs, fallbackText, latex);
    }).catch
